<?php
namespace Tests\Feature\Admin;
use App\Enums\LeadStatus;use App\Livewire\Admin\Customers\Create as CreateCustomer;use App\Livewire\Admin\Customers\Edit as EditCustomer;use App\Livewire\Admin\Tours\Create as CreateTour;use App\Livewire\Admin\Tours\Edit as EditTour;use App\Models\Customer;use App\Models\Invoice;use App\Models\Lead;use App\Models\Tour;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Livewire\Livewire;use Tests\TestCase;
class CustomerTourWorkspaceTest extends TestCase{use RefreshDatabase;
 public function test_admin_can_create_edit_and_view_customer_history():void{$admin=User::factory()->create(['role'=>'admin']);$this->actingAs($admin);Livewire::test(CreateCustomer::class)->set('name','Jane Traveller')->set('email','jane@example.test')->call('save')->assertHasNoErrors();$customer=Customer::firstOrFail();Livewire::test(EditCustomer::class,['customer'=>$customer])->set('phone','0771234567')->call('save')->assertHasNoErrors();$lead=Lead::factory()->create(['customer_id'=>$customer->id,'customer_name'=>$customer->name]);Invoice::factory()->create(['lead_id'=>$lead->id,'total_amount'=>1000,'balance_amount'=>600]);$this->get(route('admin.customers.show',$customer))->assertOk()->assertSee('Jane Traveller')->assertSee('600.00');$this->assertSame('0771234567',$customer->fresh()->contact_info['phone']);}
 public function test_account_can_create_edit_and_view_tour_financials():void{$account=User::factory()->create(['role'=>'account']);$this->actingAs($account);Livewire::test(CreateTour::class)->set('name','Japan Autumn')->set('departure_date',today()->addMonth()->toDateString())->set('return_date',today()->addMonth()->addWeek()->toDateString())->set('seat_capacity',20)->set('package_price',250000)->call('save')->assertHasNoErrors();$tour=Tour::firstOrFail();$this->assertNotEmpty($tour->tour_code);Livewire::test(EditTour::class,['tour'=>$tour])->set('seat_capacity',25)->call('save')->assertHasNoErrors();$lead=Lead::factory()->create(['tour_id'=>$tour->id,'is_group_lead'=>true,'number_of_adults'=>2]);Invoice::factory()->create(['lead_id'=>$lead->id,'tour_id'=>$tour->id,'total_amount'=>500000,'balance_amount'=>300000,'payment_amount'=>200000]);$this->get(route('admin.tours.show',$tour))->assertOk()->assertSee('500,000.00')->assertSee('300,000.00');$this->assertSame(25,$tour->fresh()->seat_capacity);}
 public function test_confirmed_travel_schedule_shows_departures_and_arrivals():void{$admin=User::factory()->create(['role'=>'admin']);$this->actingAs($admin);$departure=Lead::factory()->create(['status'=>LeadStatus::CONFIRMED->value,'depature_date'=>today()->addDays(3),'customer_name'=>'Departing Guest']);$arrival=Lead::factory()->create(['status'=>LeadStatus::CONFIRMED->value,'arrival_date'=>today()->subDays(2),'customer_name'=>'Arrived Guest']);$this->get(route('admin.departures.index'))->assertOk()->assertSee('Departing Guest');$this->get(route('admin.arrivals.index'))->assertOk()->assertSee('Arrived Guest');}
}
